using System;using System.IO;using UnityEngine;using UnityEditor;
public static class Boat109Review {
 public static void Compare(Camera camera,GameObject old,string output,Action draw){old.SetActive(false);draw();foreach(var stage in new[]{"before","after"}){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(stage=="before"?"Assets/Imported108-after-v3/small-rowboat.prefab":"Assets/Imported109-after-v3/small-rowboat.prefab");if(!asset)throw new Exception("Missing rowboat prefab");var o=(GameObject)PrefabUtility.InstantiatePrefab(asset);o.transform.SetPositionAndRotation(old.transform.position,Quaternion.Euler(0,0,0));Capture(camera,o,output,stage,()=>{});UnityEngine.Object.DestroyImmediate(o);}old.SetActive(true);File.WriteAllText(Path.Combine(output,"rowboat.json"),"{\"pass\":true,\"sameCameraLighting\":true,\"scale\":1,\"sourceScenesSaved\":false,\"playerExecuted\":false}");}
 static void Capture(Camera camera,GameObject root,string output,string name,Action draw){draw();var planes=GeometryUtility.CalculateFrustumPlanes(camera);int visible=0;foreach(var r in root.GetComponentsInChildren<Renderer>())if(GeometryUtility.TestPlanesAABB(planes,r.bounds))visible++;if(visible<1)throw new Exception("Boat must be in the capture frustum");ShaderUtil.allowAsyncCompilation=false;var rt=new RenderTexture(1600,900,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);camera.targetTexture=rt;for(int k=0;k<4;k++)camera.Render();foreach(var r in root.GetComponentsInChildren<Renderer>())foreach(var m in r.sharedMaterials)if(ShaderUtil.ShaderHasError(m.shader))throw new Exception(m.shader.name);var prev=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(1600,900,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,1600,900),0,0);im.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),im.EncodeToPNG());RenderTexture.active=prev;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(im);}
}
